package ec.edu.ucuenca.mda.vuelos.service;
import ec.edu.ucuenca.mda.vuelos.domain.*;
import ec.edu.ucuenca.mda.vuelos.dto.*;
import ec.edu.ucuenca.mda.vuelos.repository.*;
import ec.edu.ucuenca.mda.vuelos.support.*;
import java.time.*;
import java.util.*;
import org.springframework.data.domain.Sort;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
@Service
@Transactional(readOnly=true)
public class VueloService {
    private final VueloRepository repository;
    private final RutaRepository rutaRepository;
    private final AvionRepository avionRepository;
    private final ReservaRepository reservaRepository;
    private final Clock clock;
    public VueloService(VueloRepository repository, RutaRepository rutaRepository, AvionRepository avionRepository, ReservaRepository reservaRepository, Clock clock) {
        this.repository = repository;
        this.rutaRepository = rutaRepository;
        this.avionRepository = avionRepository;
        this.reservaRepository = reservaRepository;
        this.clock = clock;
    }
    private VueloResponse response(Vuelo value) {
        return VueloResponse.from(value, value.getAvion().getCapacidad() - (int) reservaRepository.countByVuelo_IdAndEstado(value.getId(), EstadoReserva.CONFIRMADA));
    }
    public VueloResponse get(Long id) { return response(repository.findById(id).orElseThrow(() -> BusinessException.notFound("Vuelo no encontrado"))); }
    public List<VueloResponse> list() { return repository.findAll(Sort.by("id")).stream().map(this::response).toList(); }
    @Transactional
    public VueloResponse create(VueloRequest request) {
        Ruta ruta = rutaRepository.findById(request.rutaId()).orElseThrow(() -> BusinessException.notFound("Ruta no encontrado"));
        Avion avion = avionRepository.lockById(request.avionId()).orElseThrow(() -> BusinessException.notFound("Avion no encontrado"));
        BusinessException.check(request.llegada().isAfter(request.salida()), "RN-02", "La llegada debe ser posterior a la salida");
        BusinessException.check(request.salida().isAfter(OffsetDateTime.now(clock)), "RN-12", "La salida debe ser futura");
        BusinessException.check(!repository.existsOverlap(avion.getId(), request.salida(), request.llegada()), "RN-08", "El avion tiene un vuelo con horario incompatible");
        Vuelo value = new Vuelo();
        value.setCodigo(request.codigo() == null ? null : request.codigo().trim().toUpperCase(Locale.ROOT));
        value.setSalida(request.salida().withOffsetSameInstant(ZoneOffset.UTC));
        value.setLlegada(request.llegada().withOffsetSameInstant(ZoneOffset.UTC));
        value.setRuta(ruta);
        value.setAvion(avion);
        return response(repository.saveAndFlush(value));
    }
    public List<VueloResponse> available(Long origenId, Long destinoId) {
        return repository.findAvailable(OffsetDateTime.now(clock), origenId, destinoId, EstadoReserva.CONFIRMADA).stream().map(this::response).toList();
    }
}
